-- Sovietski: the SN-357 Storm Swell submarine and transport and the SN-686 Typhoon II ballistic missile submarine, their sonar, decoy and stealth systems carried as features (printed 207-212).
-- 2 vehicle rows, with 29 locations and 7 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~393-sovietski-v8.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('sn-357-storm-swell', 'SN-357 Storm Swell Submarine and Transport', 'rifts', 'ship', '58: 12 officers, 36 enlisted and 10 naval airmen flying the Stormbringer gunships and Red Squall VTOLs.', 'The troop bay holds 180 infantry or Light Machines; or else 100 Heavy Machines; or else 60 Superheavy Machines; plus, as vehicles, 2 Stormbringer gunships, 8-12 Street Sickle cyborg assault trikes and 6-12 Red Squall assault platforms; in practice a mixed force of these plus the vehicles. Another load seen is a pair of SM-451 Black Water amphibious assault vehicles with their troops, 50 ordinary soldiers or Light Machines, 20 Heavy Machines and 8 Superheavy Machines. On long missions the bay doubles as living quarters and capacity usually drops by half.', 'None; it only runs up onto beaches for landings.', 'None.', '40 mph (64 km/34.7 knots) on the surface; 60 mph (96 km/51 knots) submerged. Maximum depth 1.5 miles (2.4 km).', 'Height 32 feet (9.8 m) to the bridge top; width 58 feet (17.7 m) counting the engine nacelles; length 285 feet (86.9 m).', '12,800 tons', 1100, 1, NULL, NULL, 'Almost never seen on the Black Market; a new, undamaged one would sell for 200 to 300 million credits.', 'Since the Rifts came, the Sovietski navy has leaned on this boat more than any other: an attack submarine, cruiser and amphibious landing ship in one, kept small enough that the modest military yards at the Volga River Fortress, Kaliningrad and New Leningrad can build and service it after the old capital-ship yards were lost. It is simple to maintain and copes with most conditions. The hull is long, flat and smooth, an ellipse wider than tall seen head-on, with a bridge raised roughly two thirds aft whose observation window hides behind retractable armored shutters (100 M.D.C. each). Under the bridge, wing-like nacelles run forward to roughly midships, each holding two more engines and the torpedo tubes. Three ion turrets lie flush in the deck, two ahead of the bridge and one behind, and rise only when the boat surfaces; they cannot fire submerged. Aft of the bridge a small flight deck carries two Stormbringer (SUMi-224) gunships or six Red Squall (SUMi-185) VTOL platforms for light air cover over a landing or against quick foes at sea. The bow is the troop bay, usually filled with Light, Heavy and Superheavy Machines alongside Wolverine People and Cold Born, often with two or three special forces squads. The boat closes on a beach and drops its bow door to pour troops ashore under the turrets'' covering fire, or floods the forward bay through its ballast system to release combat swimmers and amphibious Rusalka cyborgs while still submerged, then shuts and pumps it dry. It has fought the Warlords and the Brodkil Empire and kept besieged Kaliningrad supplied. The book means it as a crew posting or roaming base for player characters rather than a ship they own. Losing one engine nacelle cuts speed and handling by 30%; losing both leaves only the small directional thrusters and the tail engine, -80% speed, and no torpedoes, though it can still surface to fire missiles and fly off aircraft. Wrecking the forward section exposes the inner troop compartment and halves the beach door''s M.D.C.; wrecking that compartment tears away the front third, spilling 1D4x10+50% of its troops, vehicles and cargo into the sea, flooding the rest of it (sealed off from the ship), and forcing the boat to stay surfaced and limp home at -25% piloting and -20% speed. A destroyed flight deck door floods the bay when submerged, drowning anyone inside and sending the aircraft adrift (2D4x10% chance each to float off before sinking), for -10% piloting and -10% speed. A destroyed bridge takes radar, radio, sonar and every sensor with it; the weapons still work and it can still travel, but blind, best done on the surface. Nuclear, 20-year average life. Cargo: 220 tons at most, counting cargo, troops and secondary vehicles. Standard Sovietski vehicle systems plus: advanced life support (sealed, filtered air with a toxin alarm, recycled for about 120 days); desalination making as much as 1,000 gallons (3,785 liters) of drinking water a day; a galley and mess feeding crew and troops in three shifts; enhanced radar that identifies and tracks 144 targets out to 300 miles (480 km); passive sonar out to 10 miles (16 km) that sifts background noise, tracks 30 contacts and recognizes 100 vessel signatures including almost every pre-Rifts American and Soviet submarine; active sonar out to 50 miles (80 km) with the same tracking and library, seldom used because each ping betrays the boat (each sonar gives a trained operator +10% to Sensory Equipment); radios with a 100 mile (160 km) reach (directional, wide-band and FM/HF/UHF/VHF, plus satellite gear dead since the Great Cataclysm), used by floating a radio buoy or rising to periscope depth, 100 feet (30 m),, with telephones and a public address system inside; acoustic decoys, 20 carried, fired in pairs from mini-tubes amidships, each mimicking the boat''s sound only louder for a 50% chance to pull an ordinary torpedo off course, one melee to reload the tubes; and a sonar buoy streamed just under the surface to ping and scan downward, finding quiet or stealthy craft without exposing the boat (some enemies will shoot at it, reading it as a surfaced sub); the captain can reel it in silently or cut it loose, and a spare is fitted in about five minutes.', 'Rifts World Book 36: Sovietski p.207-209'),
  ('sn-686-typhoon-ii', 'SN-686 Typhoon II Ballistic Missile Submarine', 'rifts', 'ship', '160: 18 officers and 142 enlisted crew.', 'A standard 40 naval infantry in any mix of partial conversion cyborgs, lightly augmented or normal humans, and Light, Heavy or Superheavy Machines; Heavy and Superheavy Machines each fill two soldiers'' space. The usual mix is 10 lightly augmented humans or partial conversions, 18 Light Machines, 6 Heavy and 6 Superheavy Machines.', 'None.', 'None.', '30 mph (48 km) on the surface; 90 mph (144 km) submerged. Maximum depth 5 miles (8 km).', 'Length 612 feet (186.5 m); width 94 feet (28.7 m); height 85 feet (25.9 m) to the bridge top.', '16,400 tons', 1650, 1, NULL, NULL, 'Not available; unique to the Sovietski.', 'A pre-Rifts Soviet redesign of the Typhoon class, the largest submarine of its age, rushed into being when spies reported an American super-sub (the USS Ticonderoga) under development. It never matched the Ticonderoga, and next to that boat or comparable NGR vessels its quarters are bare: no theater or gym, since the brass treat it as a working warship, and cards, books, cigarettes and vodka count as essential stores. Built a little bigger and broader than the original Typhoons from Mega-Damage alloys that let it dive very deep and soak up punishment. Sixteen were built; half died in or soon after the Great Cataclysm and the rest went missing, four of them at Murmansk, which the Sovietski raided after leaving their bunker and found largely spared by the Eighty Years of Winter and its far-north position. They cut the four boats out of the ice and took them to the retaken New Leningrad yards, the start of today''s makeshift navy. Two are now on patrol across the Black, Baltic, North and Barents Seas, rotating out for two months of rest and refit between tours; each can stay down six months, recycling air, desalinating water and carrying enough food. Crew and troops are kept busy with small jobs and missions, and Heavy and Superheavy Machines can plug into a virtual-reality link to talk with shipmates over displays instead of squeezing through the narrow passages. The 14 vertical tubes take medium or long-range missiles and can take nuclear ones on government or military order; rumor holds that one boat always carries 14 nukes with orders to wipe out every Warlord stronghold if the Sovietski falls, which many call propaganda but which still gives the Warlords pause. The book means it as a crew posting or roaming base for player characters, not a ship they command. If the sail bridge is lost, a secondary command center runs the boat at no penalty; losing the forward section destroys the torpedo tubes and deck gun and drops the torpedoes to the sea floor. Cargo: 300 tons at most, counting cargo, troops and secondary vehicles, every bit of it loaded through the big hatch behind the bridge tower. Nuclear, 20-year average life. Stealth: the anechoic hull swallows sonar pings, putting anyone reading or identifying it at -25% to Sensory Equipment, and a hull coating, a reactor that circulates water by convection rather than pumps and a magneto-hydrodynamic drive make it one of the quietest nuclear subs on Earth, a further -20% to enemy sonar operators trying to find it. Standard Sovietski vehicle systems plus: active sonar out to 50 miles (80 km) tracking 30 contacts with the passive library, rarely used since it reveals the boat; passive sonar out to 10 miles (16 km) that sifts background noise, tracks 30 contacts and recognizes 100 vessel signatures every pre-Rifts Soviet and American submarine among them (each sonar gives a trained operator +10% to Sensory Equipment); acoustic decoys, 20 carried, fired in pairs from mini-tubes amidships, each a louder copy of the boat''s sound with a 50% chance to draw off an ordinary torpedo, one melee to reload; radios with a 100 mile (160 km) reach (directional, wide-band, FM/HF/UHF/VHF and satellite), used through a radio buoy or at a periscope depth of 100 feet (30 m), with telephones and a public address system inside; an electronic counter-measure system that jams every enemy transmission within 30 miles (48 km) and, tied to the radar and combat computer, traces broadcasts on jammed channels and homing beacons to their rough source; enhanced radar identifying and tracking 144 targets out to 300 miles (480 km); a galley and mess serving crew and troops in three shifts; a sonar buoy run just under the surface to ping and scan downward for quiet craft without exposing the sub (some foes will fire on it as a surfaced boat), reeled in silently or cut loose, with a spare fitted in about five minutes; and desalination making up to 1,000 gallons of fresh water a day.', 'Rifts World Book 36: Sovietski p.210-212');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('sn-357-storm-swell', 'Pop-Up Forward Ion Turret', 200, 'One, in the bow.', 1),
  ('sn-357-storm-swell', 'Pop-Up Middle Ion Turrets (2)', 200, 'Each; one on each side of the bridge.', 2),
  ('sn-357-storm-swell', 'Pop-Up Medium-Range Missile Launcher', 100, 'One, center deck.', 3),
  ('sn-357-storm-swell', 'Pop-Up Short-Range Missile Launchers (2)', 100, 'Each; mid-deck.', 4),
  ('sn-357-storm-swell', 'Torpedo Tubes (4)', 100, 'Each; two per nacelle. Small target: Called Shot only, -3 to strike.', 5),
  ('sn-357-storm-swell', 'Wing-like Nacelles (2)', 200, 'Each; one on each side.', 6),
  ('sn-357-storm-swell', 'Engines in the Nacelles (2)', 100, 'Each. One nacelle lost: -30% speed and maneuverability. Both lost: -80% speed and no torpedoes.', 7),
  ('sn-357-storm-swell', 'Engine in Tail', 120, 'See the nacelle engines for the speed losses.', 8),
  ('sn-357-storm-swell', 'Aircraft Landing Bay Door', 250, 'One, stern top. Destroyed, the bay floods when submerged: -10% piloting and -10% speed.', 9),
  ('sn-357-storm-swell', 'Beach Landing Bay Door', 300, 'Bow/nose. Halved when the forward section is depleted.', 10),
  ('sn-357-storm-swell', 'Hatches/Airlocks (6)', 120, 'Each. Small target: Called Shot only, -3 to strike.', 11),
  ('sn-357-storm-swell', 'Communications Tower', 100, 'One, on the bridge. Small target: Called Shot only, -3 to strike. Destroying it knocks out long-range radio, radar and surface sensors; on the surface the crew loses the bonuses of the ship''s special features.', 12),
  ('sn-357-storm-swell', 'Sensor Array', 50, 'One, on the bridge. Small target: Called Shot only, -3 to strike.', 13),
  ('sn-357-storm-swell', 'Sonar Array', 50, 'One, on the bridge. Small target: Called Shot only, -3 to strike. Destroying it leaves the boat blind underwater.', 14),
  ('sn-357-storm-swell', 'Forward 1/3 of the Ship/Troop Bay', 400, 'Depleting it exposes the reinforced troop compartment and halves the Beach Landing Bay Door''s M.D.C.', 15),
  ('sn-357-storm-swell', 'Reinforced Forward Troop Transport Compartment', 250, 'Depleting it tears off the front third; see the description.', 16),
  ('sn-357-storm-swell', 'Bridge', 400, 'Destroying it takes out radar, radio, sonar and all sensors; the boat fights and moves blind.', 17),
  ('sn-357-storm-swell', 'Main Body', 1100, 'Depleting it breaks the hull and the boat sinks within 1D6x10 minutes; shallower than 600 feet (183 m) it can surface first to get troops off. Deeper than 2,000 feet (610 m), water pressure crushes it and every cyborg aboard.', 18),
  ('sn-686-typhoon-ii', 'Pop-Up Deck Gun/Cannon', 400, 'Destroyed with the forward section.', 1),
  ('sn-686-typhoon-ii', 'Vertical Launch Missile Tubes (14)', 120, 'Each; on top. Small target: Called Shot only, -3 to strike.', 2),
  ('sn-686-typhoon-ii', 'External Hatches (3)', 80, 'Each; one per side plus one on the bridge. Small target: Called Shot only, -3 to strike.', 3),
  ('sn-686-typhoon-ii', 'Large External Hatch', 200, 'One, behind the bridge. Small target: Called Shot only, -3 to strike.', 4),
  ('sn-686-typhoon-ii', 'Torpedo Tubes (6)', 100, 'Each; bow/nose. Small target: Called Shot only, -3 to strike. Destroyed with the forward section.', 5),
  ('sn-686-typhoon-ii', 'Retractable Bow Hydroplanes (2)', 200, 'Each; bow. Small target: Called Shot only, -3 to strike.', 6),
  ('sn-686-typhoon-ii', 'Rudders (2)', 200, 'Each. Small target: Called Shot only, -3 to strike.', 7),
  ('sn-686-typhoon-ii', 'Periscopes (2)', 50, 'Each (printed as Periscope (2)). Small target: Called Shot only, -3 to strike.', 8),
  ('sn-686-typhoon-ii', 'Sail Bridge', 600, 'If destroyed, a secondary Command and Control Center runs the boat at no penalty.', 9),
  ('sn-686-typhoon-ii', 'Forward 1/3 of the Ship/Launch Section', 900, 'Depleting it destroys the torpedo tubes and the deck gun, and the torpedoes sink to the sea floor.', 10),
  ('sn-686-typhoon-ii', 'Main Body', 1650, 'Depleting it breaks the hull and the boat sinks; deeper than 2,000 feet (610 m), water pressure crushes it with everyone aboard.', 11);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sn-357-storm-swell', 1, 'Pop-Up Ion Turrets (3)', '2D4x10 M.D. per dual blast; the two cannons always fire as a pair', 1, '3,000 feet (914 m)', 'Each blast uses one melee attack.', 'Effectively unlimited.', NULL, 'Twin-barreled turrets that rise from the deck once the boat surfaces, one in the bow and one beside each side of the bridge; each turns 360 degrees and tilts 75 degrees up or down under its own gunner. Defense and troop support, then anti-ship and assault.'),
  ('sn-357-storm-swell', 2, 'Pop-Up Medium-Range Missile Box Launcher', 'Varies with the missile; typically heavy high explosive, 3D6x10 M.D. to a 20 foot (6.1 m) radius. The book refers to Rifts Ultimate Edition p.363 for other types.', 1, 'Varies with the missile; typically 40 miles (64 km)', 'One at a time or volleys of 2, 4 or 6.', '6 in the launcher plus 6 more in storage; the experienced crew reloads by hand in 2D4+4 minutes.', NULL, 'A hidden launcher near the middle of the deck that fires only on the surface, worked by its own gunner. Anti-ship and entrenched positions, then assault and defense.'),
  ('sn-357-storm-swell', 3, 'Pop-Up Short-Range Missile Box Launchers (2)', 'Varies with the missile; any short-range type, usually medium high explosive (2D6x10 M.D. to a 15 foot/4.6 m radius) or plasma (2D6x10 M.D. to a 15 foot/4.6 m radius)', 1, '5 miles (8 km)', 'One at a time or volleys of 2, 4 or 6.', '24 in all, 12 per launcher (the description also says 8 per box), plus 32 in storage; hand reloading takes the experienced crew 1D6+4 minutes per launcher.', NULL, 'Two boxes mid-deck ahead of the bridge that lift three feet (0.9 m) when surfaced, each turning 360 degrees and tilting 60 degrees under its own gunner; aimed at aircraft and flying monsters, or ships and shore emplacements during landings. Anti-flyer and anti-ship, then assault and defense.'),
  ('sn-357-storm-swell', 4, 'Medium Torpedo Tubes (4)', '3D6x10 M.D. per high explosive torpedo', 1, '20 miles (32 km)', 'Singly or in pairs; an automatic magazine reloads each tube, so up to three volleys per melee round.', '24 torpedoes, 6 per tube.', NULL, 'Two tubes at the front of each engine nacelle (the text also calls them heavy), used on submarines, ships and big sea creatures. Anti-ship/anti-submarine, then assault.'),
  ('sn-686-typhoon-ii', 1, 'Concealed 200mm Heavy Deck Gun', 'High explosive: 2D6x10 M.D. to a 10 foot (3 m) radius per single blast, or 4D6x10 M.D. when both barrels fire together at one target', 1, '12,000 feet (3,658 m, roughly 2 miles/3.2 km)', 'One shell or two at once, either way using one melee attack; the loader limits it to four blasts per melee round.', '100 dual shots or 200 single shots per internal magazine.', NULL, 'A double-barreled cannon on the bow center line that pops up from its housing, turns 360 degrees and tilts 75 degrees under its own gunner. Its housing also holds a mini-missile launcher: 24 high explosive mini-missiles (5D6 M.D. each), singly or in volleys of 2, 4 or 6 out to a mile (1.6 km), with one reload aboard taking 1D6+2 minutes. Anti-ship, then assault.'),
  ('sn-686-typhoon-ii', 2, 'VLS Missile Launchers (14)', 'Varies with the missile; the standard load is 10 heavy high explosive (4D6x10 M.D.) and 4 medium plasma (4D6x10 M.D.). The book refers to Rifts Ultimate Edition p.363 for other types, nuclear warheads included.', 1, 'Most long-range missiles reach 500 miles (800 km); nuclear-tipped ones 1,000 miles (1,600 km)', 'One at a time or volleys of 2, 3, 4 or 6.', '14 missiles. The Sovietski hold no more than two dozen nuclear missiles in all.', NULL, 'Fourteen vertical launch tubes set in the deck ahead of the bridge tower, usually loaded with long-range missiles, medium-range when long-range are short; any medium or long-range type fits. Anti-ship, then anti-city.'),
  ('sn-686-typhoon-ii', 3, 'Torpedo Tubes (6)', '3D6x10 M.D. per medium high explosive or plasma torpedo', 1, '10 miles (16 km)', 'One at a time or volleys of two; an automatic magazine reloads each tube, so up to four volleys per melee.', '48 torpedoes, 8 per tube.', NULL, 'Six heavy tubes in the bow, three per side, used on submarines, warships, big sea creatures and other naval targets. Anti-ship/anti-submarine, then assault and defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sn-357-storm-swell', 'sn-686-typhoon-ii');
SELECT 'their 29 locations are in' AS assertion, count(*) AS got, 29 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sn-357-storm-swell', 'sn-686-typhoon-ii');
SELECT 'their 7 weapon entries are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sn-357-storm-swell', 'sn-686-typhoon-ii');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sn-357-storm-swell', 'sn-686-typhoon-ii') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

